using Callsign.Extensions;

namespace Callsign.UI.Services;

public sealed record CommandDiscoveryEntry(
    string Category,
    string Phrase,
    string Description,
    CallsignCommandRiskTier RiskTier,
    CallsignCommandApprovalRequirement ApprovalRequirement,
    string Source,
    IReadOnlyList<string>? VoicePhrases = null,
    IReadOnlyList<string>? Examples = null,
    CallsignPackTier Tier = CallsignPackTier.Free,
    CallsignPackLoadStatus LoadStatus = CallsignPackLoadStatus.Loaded,
    string Availability = "Available");

public static class CommandDiscoveryService
{
    private const string BuiltInSource = "Built-in Free core";

    public static IReadOnlyList<CommandDiscoveryEntry> GetCommands(CallsignCommandRegistry? registry = null)
    {
        var commands = new List<CommandDiscoveryEntry>();
        commands.AddRange(GetBuiltInCommands().Select(command => command with { Source = BuiltInSource }));

        registry ??= CallsignCommandRegistry.Shared;
        foreach (var command in registry.GetCommands())
        {
            var definition = command.Definition;
            var phrase = definition.VoicePhrases.FirstOrDefault() ?? command.CommandDisplayName;
            var examples = MergeExamples(definition.VoicePhrases, definition.Examples);
            var availability = FormatAvailability(command.LoadStatus, command.Tier);
            commands.Add(new CommandDiscoveryEntry(
                string.IsNullOrWhiteSpace(definition.Category) ? definition.Kind.ToString() : definition.Category,
                phrase,
                definition.HelpText ?? definition.Description,
                definition.RiskTier,
                definition.ApprovalRequirement,
                $"{command.PackDisplayName} [{command.Tier}; {availability}]",
                definition.VoicePhrases,
                examples,
                command.Tier,
                command.LoadStatus,
                availability));
        }

        return commands
            .OrderBy(command => command.Category, StringComparer.OrdinalIgnoreCase)
            .ThenBy(command => command.Phrase, StringComparer.OrdinalIgnoreCase)
            .ToArray();
    }

    public static string BuildHelpText(CallsignCommandRegistry? registry = null)
    {
        var groups = GetCommands(registry)
            .GroupBy(command => command.Category)
            .OrderBy(group => group.Key, StringComparer.OrdinalIgnoreCase);

        var lines = new List<string>
        {
            "Callsign command palette",
            string.Empty,
            "Say Callsign, verify your callsign, then speak one of these commands.",
            "Try getting started to reopen the setup walkthrough.",
            "Search tips: try category:System, category:Browser, category:Dictation, tier:free, tier:pro, tier:advanced, status:available, status:disabled, status:gated, or source:Built-in Free core or source:Sample Pack.",
            string.Empty
        };

        foreach (var group in groups)
        {
            lines.Add(group.Key);
            foreach (var command in group)
            {
                var aliases = command.VoicePhrases is { Count: > 1 }
                    ? $" ({string.Join(", ", command.VoicePhrases.Skip(1).Take(4))})"
                    : string.Empty;
                var examples = FormatExampleHint(command);
                var availability = command.LoadStatus == CallsignPackLoadStatus.Loaded
                    ? string.Empty
                    : $" [{command.Availability}]";
                lines.Add($"- {command.Phrase}{aliases}: {command.Description}{examples}{availability}");
            }
            lines.Add(string.Empty);
        }

        lines.Add("Safety");
        lines.Add("- cancel: stop the current session");
        lines.Add("- stop listening: stop voice capture");
        lines.Add("- reset session: return to idle");

        return string.Join(Environment.NewLine, lines);
    }

