    private static IReadOnlyList<string> MergeExamples(IReadOnlyList<string>? primary, IReadOnlyList<string>? secondary)
    {
        if ((primary is null || primary.Count == 0) && (secondary is null || secondary.Count == 0))
            return Array.Empty<string>();

        var merged = new List<string>();
        AddDistinct(merged, primary);
        AddDistinct(merged, secondary);
        return merged;
    }

    private static void AddDistinct(List<string> target, IReadOnlyList<string>? values)
    {
        if (values is null)
            return;

        foreach (var value in values)
        {
            if (string.IsNullOrWhiteSpace(value))
                continue;

            if (target.Any(existing => string.Equals(existing, value, StringComparison.OrdinalIgnoreCase)))
                continue;

            target.Add(value);
        }
    }

    private static string FormatAvailability(CallsignPackLoadStatus loadStatus, CallsignPackTier tier) =>
        loadStatus switch
        {
            CallsignPackLoadStatus.Loaded => "Available",
            CallsignPackLoadStatus.Disabled => "Disabled until enabled from Packs",
            CallsignPackLoadStatus.EntitlementRequired => $"{tier} entitlement required; listed for discovery only and will not route",
            CallsignPackLoadStatus.SignatureRequired => "Valid signature required; listed for discovery only and will not route",
            CallsignPackLoadStatus.MissingAssembly => "Missing assembly",
            CallsignPackLoadStatus.MissingPackType => "Invalid pack",
            CallsignPackLoadStatus.DuplicatePackId => "Duplicate pack",
            CallsignPackLoadStatus.InvalidPack => "Invalid pack",
            CallsignPackLoadStatus.LoadFailure => "Load failure",
            _ => loadStatus.ToString()
        };

    private static string FormatExampleHint(CommandDiscoveryEntry command)
    {
        if (command.Examples is not { Count: > 0 })
            return string.Empty;

        var candidates = command.Examples
            .Where(example => !string.IsNullOrWhiteSpace(example))
            .Where(example => !string.Equals(example, command.Phrase, StringComparison.OrdinalIgnoreCase))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .ToArray();
        var examples = candidates
            .Take(2)
            .Concat(candidates.Skip(Math.Max(0, candidates.Length - 2)))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Take(4)
            .ToArray();

        return examples.Length == 0
            ? string.Empty
            : $" Try: {string.Join("; ", examples)}.";
    }
